package com.google.gson.internal;

import java.io.*;
import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class UnsafeAllocator_create_TriageGen2Test {

    @Test
    public void testCreateWithJVMUnsafe() throws Exception {
        // Mock reflection for sun.misc.Unsafe
        Class<?> mockUnsafeClass = mock(Class.class, RETURNS_SMART_NULLS);
        when(mockUnsafeClass.getDeclaredField("theUnsafe")).thenReturn(mock(Field.class));
        when(mockUnsafeClass.getMethod("allocateInstance", Class.class)).thenReturn(mock(Method.class));

        // Mock the UnsafeAllocator to check if newInstance uses sun.misc.Unsafe
        UnsafeAllocator allocator = UnsafeAllocator.create();
        allocator.newInstance(String.class);

        // Verify that the sun.misc.Unsafe path was taken
        verify(mockUnsafeClass).getMethod("allocateInstance", Class.class);
    }

    @Test
    public void testCreateWithDalvikvmPostGingerbread() throws Exception {
        // Mock reflection for ObjectStreamClass
        Method mockGetConstructorId = mock(Method.class);
        Method mockNewInstance = mock(Method.class);

        when(ObjectStreamClass.getDeclaredMethod("getConstructorId", Class.class)).thenReturn(mockGetConstructorId);
        when(mockGetConstructorId.invoke(null, Object.class)).thenReturn(123); // Mock constructorId
        when(ObjectStreamClass.getDeclaredMethod("newInstance", Class.class, int.class)).thenReturn(mockNewInstance);

        // Mock the UnsafeAllocator to check if newInstance uses ObjectStreamClass
        UnsafeAllocator allocator = UnsafeAllocator.create();
        allocator.newInstance(String.class);

        // Verify that the ObjectStreamClass path was taken
        verify(mockNewInstance).invoke(null, String.class, 123);
    }

    @Test
    public void testCreateWithDalvikvmPreGingerbread() throws Exception {
        // Mock reflection for ObjectInputStream
        Method mockNewInstance = mock(Method.class);

        when(ObjectInputStream.getDeclaredMethod("newInstance", Class.class, Class.class)).thenReturn(mockNewInstance);

        // Mock the UnsafeAllocator to check if newInstance uses ObjectInputStream
        UnsafeAllocator allocator = UnsafeAllocator.create();
        allocator.newInstance(String.class);

        // Verify that the ObjectInputStream path was taken
        verify(mockNewInstance).invoke(null, String.class, Object.class);
    }

    @Test
    public void testCreateFallbackUnsupportedOperationException() {
        // Mock reflection to throw exceptions for all reflection paths
        doThrow(new ClassNotFoundException()).when(Class.class).forName("sun.misc.Unsafe");
        doThrow(new NoSuchMethodException()).when(Class.class).getDeclaredMethod(anyString(), any());

        UnsafeAllocator allocator = UnsafeAllocator.create();

        try {
            allocator.newInstance(String.class);
            fail("Expected UnsupportedOperationException to be thrown");
        } catch (UnsupportedOperationException e) {
            assertNotNull(e.getMessage());
            assertTrue(e.getMessage().contains("Cannot allocate"));
        }
    }
}
